    level: "Hard",
    topic: "Strings & Regex",
    title: "Parse a CSV line with quoted fields",
    task: "Nimbus Fleet imports supplier CSV files through a Visualforce upload. Write `public static List<String> parseLine(String line)` in class `CsvParser`.\n- Fields are separated by commas\n- A field wrapped in double quotes may contain commas\n- Inside quotes, two double quotes (\"\") mean one literal quote\n- Empty fields are kept as '' (so 'a,,b' gives 3 fields)\n- Null input returns an empty list\n- An unterminated quote throws IllegalArgumentException\n- A plain split(',') is not acceptable",
    starter: "public with sharing class CsvParser {\n    public static List<String> parseLine(String line) {\n        // TODO\n        return new List<String>();\n    }\n}\n",
    solution: "public with sharing class CsvParser {\n    public static List<String> parseLine(String line) {\n        List<String> fields = new List<String>();\n        if (line == null) return fields;\n        String current = '';\n        Boolean inQuotes = false;\n        Integer len = line.length();\n        Integer i = 0;\n        while (i < len) {\n            String ch = line.substring(i, i + 1);\n            if (inQuotes) {\n                if (ch == '\"') {\n                    if (i + 1 < len && line.substring(i + 1, i + 2) == '\"') {\n                        current += '\"';\n                        i++;\n                    } else {\n                        inQuotes = false;\n                    }\n                } else {\n                    current += ch;\n                }\n            } else if (ch == '\"') {\n                inQuotes = true;\n            } else if (ch == ',') {\n                fields.add(current);\n                current = '';\n            } else {\n                current += ch;\n            }\n            i++;\n        }\n        if (inQuotes) {\n            throw new IllegalArgumentException('Unterminated quoted field');\n        }\n        fields.add(current);\n        return fields;\n    }\n}\n",
    checks: [{ re: /List<\s*String\s*>\s+parseLine\s*\(\s*String\s+\w+\s*\)/i, msg: "Keeps the required method signature" }, { re: /for\s*\(|while\s*\(/i, msg: "Walks the line character by character" }, { re: /'"'|'\\"'|34\b/, msg: "Handles the double-quote character" }, { re: /IllegalArgumentException/i, msg: "Throws IllegalArgumentException for an unterminated quote" }],
    forbid: [{ re: /\.split\(\s*','\s*\)/i, msg: "A naive split(',') breaks quoted commas" }],
    hints: ["Track a Boolean inQuotes flag while scanning.", "When you see a quote inside quotes, peek at the next character: another quote is an escaped quote, otherwise the quoted section ends."],
    ai: "Check quoted commas, escaped \"\" quotes, empty fields (including a trailing comma), unterminated quotes throwing, and that the result for a simple unquoted line matches split semantics."
