    solution: "public with sharing class DuplicateFinder {\n    public static Map<String, List<Id>> findDuplicates() {\n        Set<String> emails = new Set<String>();\n        for (AggregateResult ar : [\n            SELECT Email, COUNT(Id) cnt\n            FROM Contact\n            WHERE Email != null\n            WITH USER_MODE\n            GROUP BY Email\n            HAVING COUNT(Id) > 1\n            ORDER BY COUNT(Id) DESC\n            LIMIT 200\n        ]) {\n            emails.add((String) ar.get('Email'));\n        }\n        Map<String, List<Id>> result = new Map<String, List<Id>>();\n        if (emails.isEmpty()) return result;\n        for (Contact c : [\n            SELECT Id, Email\n            FROM Contact\n            WHERE Email IN :emails\n            WITH USER_MODE\n            ORDER BY CreatedDate ASC\n        ]) {\n            String key = c.Email.toLowerCase();\n            if (!result.containsKey(key)) result.put(key, new List<Id>());\n            result.get(key).add(c.Id);\n        }\n        return result;\n    }\n}\n",
