    starter: "public with sharing class CustomerSync {\n    public class CustomerDto {\n        public String erpId;\n        public String name;\n        public String postcode;\n    }\n\n    public static Map<String, String> upsertCustomers(List<CustomerDto> rows) {\n        // TODO\n        return new Map<String, String>();\n    }\n}\n",
    solution: "public with sharing class CustomerSync {\n    public class CustomerDto {\n        public String erpId;\n        public String name;\n        public String postcode;\n    }\n\n    public static Map<String, String> upsertCustomers(List<CustomerDto> rows) {\n        Map<String, String> outcome = new Map<String, String>();\n        if (rows == null || rows.isEmpty()) return outcome;\n        List<Account> accounts = new List<Account>();\n        for (CustomerDto row : rows) {\n            if (row == null || String.isBlank(row.erpId)) continue;\n            accounts.add(new Account(\n                ERP_Id__c = row.erpId,\n                Name = row.name,\n                BillingPostalCode = row.postcode\n            ));\n        }\n        if (accounts.isEmpty()) return outcome;\n        List<Database.UpsertResult> results = Database.upsert(accounts, Account.ERP_Id__c, false, AccessLevel.USER_MODE);\n        for (Integer i = 0; i < results.size(); i++) {\n            Database.UpsertResult res = results[i];\n            String erpId = accounts[i].ERP_Id__c;\n            if (res.isSuccess()) {\n                outcome.put(erpId, res.isCreated() ? 'CREATED' : 'UPDATED');\n            } else {\n                outcome.put(erpId, 'FAILED: ' + res.getErrors()[0].getMessage());\n            }\n        }\n        return outcome;\n    }\n}\n",
