    starter: "public with sharing class ContactImport {\n    public class ImportResult {\n        public List<Id> successIds = new List<Id>();\n        public Map<Integer, String> errorsByRow = new Map<Integer, String>();\n    }\n\n    public static ImportResult run(List<Contact> rows) {\n        // TODO\n        return new ImportResult();\n    }\n}\n",
    solution: "public with sharing class ContactImport {\n    public class ImportResult {\n        public List<Id> successIds = new List<Id>();\n        public Map<Integer, String> errorsByRow = new Map<Integer, String>();\n    }\n\n    public static ImportResult run(List<Contact> rows) {\n        ImportResult result = new ImportResult();\n        if (rows == null || rows.isEmpty()) return result;\n        Database.DMLOptions opts = new Database.DMLOptions();\n        opts.OptAllOrNone = false;\n        opts.DuplicateRuleHeader.allowSave = true;\n        List<Database.SaveResult> saveResults = Database.insert(rows, opts, AccessLevel.USER_MODE);\n        for (Integer i = 0; i < saveResults.size(); i++) {\n            Database.SaveResult sr = saveResults[i];\n            if (sr.isSuccess()) {\n                result.successIds.add(sr.getId());\n                continue;\n            }\n            List<String> messages = new List<String>();\n            for (Database.Error err : sr.getErrors()) {\n                List<String> fields = err.getFields();\n                String suffix = fields.isEmpty() ? '' : ' [' + String.join(fields, ', ') + ']';\n                messages.add(String.valueOf(err.getStatusCode()) + ': ' + err.getMessage() + suffix);\n            }\n            result.errorsByRow.put(i + 1, String.join(messages, ' | '));\n        }\n        return result;\n    }\n}\n",
