    starter: "public with sharing class BatchStepRunner {\n    public interface Step {\n        String label();\n        void execute();\n    }\n\n    public void runSteps(List<Step> steps) {\n        // TODO\n    }\n}\n",
    solution: "public with sharing class BatchStepRunner {\n    public interface Step {\n        String label();\n        void execute();\n    }\n\n    public class FatalStepException extends Exception {}\n\n    public Integer attempted { get; private set; }\n    public List<String> log { get; private set; }\n\n    public BatchStepRunner() {\n        attempted = 0;\n        log = new List<String>();\n    }\n\n    public void runSteps(List<Step> steps) {\n        if (steps == null) return;\n        for (Step s : steps) {\n            try {\n                s.execute();\n                log.add(s.label() + ': OK');\n            } catch (FatalStepException e) {\n                log.add(s.label() + ': FATAL ' + e.getMessage());\n                throw e;\n            } catch (Exception e) {\n                log.add(s.label() + ': FAILED ' + e.getMessage());\n            } finally {\n                attempted++;\n            }\n        }\n    }\n}\n",
