    starter: "public interface ShippingRate {\n    // TODO\n}\n\npublic with sharing class StandardRate {\n    // TODO\n}\n\npublic with sharing class NextDayRate {\n    // TODO\n}\n\npublic with sharing class ShippingQuote {\n    public static Decimal cheapest(List<ShippingRate> options, Decimal weightKg) {\n        // TODO\n        return null;\n    }\n}\n",
    solution: "public interface ShippingRate {\n    Decimal rateFor(Decimal weightKg);\n}\n\npublic with sharing class StandardRate implements ShippingRate {\n    public Decimal rateFor(Decimal weightKg) {\n        if (weightKg == null || weightKg <= 0) throw new IllegalArgumentException('Weight must be positive');\n        Decimal extraKg = weightKg > 2 ? (weightKg - 2).round(System.RoundingMode.CEILING) : 0;\n        return 4.99 + extraKg * 1.50;\n    }\n}\n\npublic with sharing class NextDayRate implements ShippingRate {\n    public Decimal rateFor(Decimal weightKg) {\n        if (weightKg == null || weightKg <= 0) throw new IllegalArgumentException('Weight must be positive');\n        return (12.50 + weightKg * 2.00).setScale(2, System.RoundingMode.HALF_UP);\n    }\n}\n\npublic with sharing class ShippingQuote {\n    public static Decimal cheapest(List<ShippingRate> options, Decimal weightKg) {\n        Decimal best;\n        if (options == null) return best;\n        for (ShippingRate option : options) {\n            Decimal rate = option.rateFor(weightKg);\n            if (best == null || rate < best) best = rate;\n        }\n        return best;\n    }\n}\n",
    checks: [{ re: /interface\s+ShippingRate\s*\{[^}]*Decimal\s+rateFor\s*\(\s*Decimal\s+\w+\s*\)/i, msg: "ShippingRate declares Decimal rateFor(Decimal)" }, { re: /implements\s+ShippingRate[\s\S]*implements\s+ShippingRate/i, msg: "Both rate classes implement ShippingRate" }, { re: /CEILING|ceil\(/i, msg: "Rounds started kilograms up" }, { re: /IllegalArgumentException/i, msg: "Rejects invalid weights" }],
    hints: ["Interface methods have no access modifier or body.", "Decimal.round(System.RoundingMode.CEILING) rounds 0.1 up to 1."],
    ai: "Verify the rate formulas (including exactly 2 kg and fractional kg above 2), validation, and that cheapest() works polymorphically through the interface."
