    title: "Fluent quote builder with inner class",
    task: "Nimbus Fleet's sales reps build vehicle-lease quotes in Apex. Create class `QuoteBuilder`:\n- Inner class `LineItem` (product, quantity, unitPrice - read-only properties) with `Decimal total()` = unitPrice x quantity, 2 dp\n- `public QuoteBuilder addLine(String product, Integer quantity, Decimal unitPrice)` - returns this for chaining; throws IllegalArgumentException for blank product, quantity <= 0 or negative/null price\n- `public QuoteBuilder withVat()` - include 20% VAT in the total\n- `public List<LineItem> getLines()` - a copy, so callers can't change the builder\n- `public Decimal total()` - sum of lines (+ VAT if set), 2 dp HALF_UP",
    starter: "public with sharing class QuoteBuilder {\n    // TODO: inner class LineItem\n\n    public QuoteBuilder addLine(String product, Integer quantity, Decimal unitPrice) {\n        // TODO\n        return null;\n    }\n\n    public Decimal total() {\n        // TODO\n        return 0;\n    }\n}\n",
    solution: "public with sharing class QuoteBuilder {\n    public class LineItem {\n        public String product { get; private set; }\n        public Integer quantity { get; private set; }\n        public Decimal unitPrice { get; private set; }\n\n        public LineItem(String product, Integer quantity, Decimal unitPrice) {\n            this.product = product;\n            this.quantity = quantity;\n            this.unitPrice = unitPrice;\n        }\n\n        public Decimal total() {\n            return (unitPrice * quantity).setScale(2, System.RoundingMode.HALF_UP);\n        }\n    }\n\n    private static final Decimal VAT_RATE = 0.20;\n    private final List<LineItem> lines = new List<LineItem>();\n    private Boolean includeVat = false;\n\n    public QuoteBuilder addLine(String product, Integer quantity, Decimal unitPrice) {\n        if (String.isBlank(product) || quantity == null || quantity <= 0 || unitPrice == null || unitPrice < 0) {\n            throw new IllegalArgumentException('Invalid quote line for ' + product);\n        }\n        lines.add(new LineItem(product, quantity, unitPrice));\n        return this;\n    }\n\n    public QuoteBuilder withVat() {\n        includeVat = true;\n        return this;\n    }\n\n    public List<LineItem> getLines() {\n        return lines.clone();\n    }\n\n    public Decimal total() {\n        Decimal net = 0;\n        for (LineItem line : lines) {\n            net += line.total();\n        }\n        Decimal gross = includeVat ? net * (1 + VAT_RATE) : net;\n        return gross.setScale(2, System.RoundingMode.HALF_UP);\n    }\n}\n",
    checks: [{ re: /class\s+LineItem/i, msg: "Defines the inner LineItem class" }, { re: /return\s+this\s*;/i, msg: "Returns this for method chaining" }, { re: /List<\s*LineItem\s*>/i, msg: "Keeps lines in a List<LineItem>" }, { re: /clone\(\)|new\s+List<\s*LineItem\s*>\s*\(\s*\w+\s*\)/i, msg: "getLines() returns a defensive copy" }, { re: /0?\.20?\b|1\.2/i, msg: "Applies 20% VAT" }],
