    starter: "public interface IOpportunitySelector {\n    List<Opportunity> selectOpenByAccount(Id accountId);\n}\n\npublic with sharing class PipelineService {\n    public Decimal weightedPipeline(Id accountId) {\n        // TODO\n        return 0;\n    }\n}\n\n@IsTest\nprivate class PipelineServiceTest {\n    // TODO\n}\n",
    solution: "public interface IOpportunitySelector {\n    List<Opportunity> selectOpenByAccount(Id accountId);\n}\n\npublic with sharing class OpportunitySelector implements IOpportunitySelector {\n    public List<Opportunity> selectOpenByAccount(Id accountId) {\n        return [\n            SELECT Id, Amount, Probability\n            FROM Opportunity\n            WHERE AccountId = :accountId AND IsClosed = false\n            WITH USER_MODE\n        ];\n    }\n}\n\npublic with sharing class PipelineService {\n    private final IOpportunitySelector selector;\n\n    public PipelineService() {\n        this(new OpportunitySelector());\n    }\n\n    @TestVisible\n    private PipelineService(IOpportunitySelector selector) {\n        this.selector = selector;\n    }\n\n    public Decimal weightedPipeline(Id accountId) {\n        Decimal total = 0;\n        if (accountId == null) return total.setScale(2);\n        for (Opportunity opp : selector.selectOpenByAccount(accountId)) {\n            if (opp.Amount == null || opp.Probability == null) continue;\n            total += opp.Amount * opp.Probability / 100;\n        }\n        return total.setScale(2, System.RoundingMode.HALF_UP);\n    }\n}\n\n@IsTest\nprivate class PipelineServiceTest {\n    private class StubSelector implements IOpportunitySelector {\n        public List<Opportunity> selectOpenByAccount(Id accountId) {\n            return new List<Opportunity>{\n                new Opportunity(Amount = 10000, Probability = 50),\n                new Opportunity(Amount = 4000, Probability = 25),\n                new Opportunity(Amount = null, Probability = 90)\n            };\n        }\n    }\n\n    @IsTest\n    static void calculatesWeightedPipelineFromStub() {\n        Id fakeAccountId = Account.SObjectType.getDescribe().getKeyPrefix() + '000000000001';\n        PipelineService service = new PipelineService(new StubSelector());\n        Assert.areEqual(6000.00, service.weightedPipeline(fakeAccountId), 'Expected 50% of 10k plus 25% of 4k');\n    }\n\n    @IsTest\n    static void returnsZeroForNullAccount() {\n        PipelineService service = new PipelineService(new StubSelector());\n        Assert.areEqual(0.00, service.weightedPipeline(null), 'Null account should give zero');\n    }\n}\n",
