    solution: "public with sharing class WorkingDays {\n    private static final Date KNOWN_MONDAY = Date.newInstance(1900, 1, 1);\n\n    public static Date addBusinessDays(Date startDate, Integer days, Set<Date> holidays) {\n        if (startDate == null || days == null || days < 0) {\n            throw new IllegalArgumentException('A start date and a non-negative day count are required');\n        }\n        Set<Date> closed = holidays == null ? new Set<Date>() : holidays;\n        Date current = startDate;\n        Integer added = 0;\n        while (added < days) {\n            current = current.addDays(1);\n            if (isBusinessDay(current, closed)) added++;\n        }\n        return current;\n    }\n\n    public static Boolean isBusinessDay(Date d, Set<Date> holidays) {\n        Integer dayIndex = Math.mod(KNOWN_MONDAY.daysBetween(d), 7);\n        Boolean weekend = dayIndex == 5 || dayIndex == 6;\n        return !weekend && (holidays == null || !holidays.contains(d));\n    }\n}\n",
    checks: [{ re: /Date\s+addBusinessDays\s*\(\s*Date\s+\w+\s*,\s*Integer\s+\w+\s*,\s*Set<\s*Date\s*>\s+\w+\s*\)/i, msg: "Keeps the required method signature" }, { re: /daysBetween\(|format\(\s*'(E|u)|toStartOfWeek\(/i, msg: "Determines the day of the week" }, { re: /\.contains\(/i, msg: "Skips holidays with Set.contains" }, { re: /addDays\(\s*1\s*\)/i, msg: "Steps forward one day at a time" }, { re: /IllegalArgumentException/i, msg: "Rejects invalid arguments" }],
    hints: ["1 Jan 1900 was a Monday: Math.mod(thatDate.daysBetween(d), 7) gives 0 = Mon ... 6 = Sun.", "Date.format() and toStartOfWeek() depend on the user's locale - avoid them for weekday logic."],
