    solution: "public with sharing class OrderWebhook {\n    public class OrderPayload {\n        public String orderId;\n        public List<Item> items;\n    }\n\n    public class Item {\n        public String sku;\n        public Integer qty;\n    }\n\n    public class PayloadException extends Exception {}\n\n    public static Integer totalQuantity(String body) {\n        if (String.isBlank(body)) return 0;\n        OrderPayload payload;\n        try {\n            payload = (OrderPayload) JSON.deserialize(body, OrderPayload.class);\n        } catch (JSONException e) {\n            throw new PayloadException('Malformed order payload', e);\n        }\n        Integer total = 0;\n        if (payload == null || payload.items == null) return total;\n        for (Item item : payload.items) {\n            if (item != null && item.qty != null && item.qty > 0) total += item.qty;\n        }\n        return total;\n    }\n}\n",
