    solution: "public with sharing class PaymentMatcher {\n    public static List<Integer> findPair(List<Integer> invoicePence, Integer paymentPence) {\n        if (invoicePence == null || paymentPence == null) return new List<Integer>();\n        Map<Integer, Integer> indexByAmount = new Map<Integer, Integer>();\n        for (Integer i = 0; i < invoicePence.size(); i++) {\n            Integer amount = invoicePence[i];\n            if (amount == null) continue;\n            Integer needed = paymentPence - amount;\n            if (indexByAmount.containsKey(needed)) {\n                return new List<Integer>{ indexByAmount.get(needed), i };\n            }\n            if (!indexByAmount.containsKey(amount)) {\n                indexByAmount.put(amount, i);\n            }\n        }\n        return new List<Integer>();\n    }\n}\n",
