    solution: "public with sharing class ProductCodeGrouper {\n    public static List<List<String>> groupAnagrams(List<String> codes) {\n        List<List<String>> result = new List<List<String>>();\n        if (codes == null) return result;\n        Map<String, List<String>> groups = new Map<String, List<String>>();\n        List<String> keysInOrder = new List<String>();\n        for (String code : codes) {\n            if (String.isBlank(code)) continue;\n            List<Integer> chars = code.toLowerCase().getChars();\n            chars.sort();\n            String key = String.fromCharArray(chars);\n            if (!groups.containsKey(key)) {\n                groups.put(key, new List<String>());\n                keysInOrder.add(key);\n            }\n            groups.get(key).add(code);\n        }\n        for (String key : keysInOrder) {\n            result.add(groups.get(key));\n        }\n        return result;\n    }\n}\n",
