    starter: "public with sharing class ListUtils {\n    public static List<List<Id>> chunk(List<Id> ids, Integer size) {\n        // TODO\n        return null;\n    }\n}\n",
    solution: "public with sharing class ListUtils {\n    public static List<List<Id>> chunk(List<Id> ids, Integer size) {\n        if (size == null || size <= 0) {\n            throw new IllegalArgumentException('Chunk size must be positive');\n        }\n        List<List<Id>> chunks = new List<List<Id>>();\n        if (ids == null) return chunks;\n        List<Id> current = new List<Id>();\n        for (Id recordId : ids) {\n            current.add(recordId);\n            if (current.size() == size) {\n                chunks.add(current);\n                current = new List<Id>();\n            }\n        }\n        if (!current.isEmpty()) chunks.add(current);\n        return chunks;\n    }\n}\n",
